style.css:
@-moz-document domain("roblox.com") {
/* TOYPAJ Album Color Palette Setup */
  :root {
    --toypaj-black: #050505 !important;
    --toypaj-dark-grey: #121212 !important;
    --toypaj-red: #ff0000 !important;    /* Airplane Icon Color */
    --toypaj-yellow: #fff100 !important; /* Pants Icon Color */
    --toypaj-green: #00ba2a !important;  /* Jacket Icon Color */
    --toypaj-white: #ffffff !important;
  }

  /* Main Website Background */
  body, 
  .wrapper, 
  .content,
  #container-main,
  .light-theme,
  .dark-theme {
    background-color: var(--toypaj-black) !important;
    background-image: none !important;
  }

  /* Roblox Top Navigation Bar */
  #header,
  .rbx-header {
    background-color: var(--toypaj-dark-grey) !important;
    border-bottom: 4px solid var(--toypaj-red) !important; /* Red Accent Line */
  }

  /* Left Sidebar Navigation */
  #navigation,
  .rbx-left-col {
    background-color: var(--toypaj-dark-grey) !important;
    border-right: 3px solid var(--toypaj-yellow) !important; /* Yellow Accent Line */
  }

  /* Game Cards & Feed Panels (Mimics the flat, bordered album inserts) */
  .section-content,
  .game-card-container,
  .item-card-container,
  .avatar-card-container,
  .places-list-container,
  .rbx-tab-content {
    background-color: var(--toypaj-dark-grey) !important;
    border: 3px solid var(--toypaj-white) !important;
    border-radius: 0px !important; /* Sharp pop-punk edges */
    box-shadow: 5px 5px 0px var(--toypaj-black) !important;
  }

  /* Headings & Usernames (Styled like the Blink-182 block logo) */
  h1, h2, h3, 
  .text-title,
  .text-name,
  .profile-header .header-names .username {
    color: var(--toypaj-white) !important;
    font-family: 'Arial Black', Impact, sans-serif !important;
    text-transform: uppercase !important;
    letter-spacing: 1px !important;
    text-shadow: 2px 2px 0px var(--toypaj-red) !important;
  }

  /* General Text & Links */
  p, span, a,
  .text-description,
  .text-label {
    color: var(--toypaj-white) !important;
  }

  /* Hovering over links turns them Green */
  a:hover,
  .text-link:hover {
    color: var(--toypaj-green) !important;
    text-decoration: none !important;
  }

  /* Roblox Green Play Button Overhauled to TOYPAJ Album Green */
  .btn-common-play-lg,
  .btn-to-play,
  .btn-primary-md {
    background-color: var(--toypaj-green) !important;
    background-image: none !important;
    color: var(--toypaj-white) !important;
    border: 3px solid var(--toypaj-white) !important;
    font-family: 'Arial Black', sans-serif !important;
    text-transform: uppercase !important;
    border-radius: 0px !important;
    box-shadow: 5px 5px 0px var(--toypaj-red) !important; /* Red shadow */
    transition: all 0.1s ease-in-out !important;
  }

  /* Play Button Interactive Hover Effect */
  .btn-common-play-lg:hover,
  .btn-to-play:hover,
  .btn-primary-md:hover {
    background-color: var(--toypaj-yellow) !important; /* Flashes yellow on hover */
    color: var(--toypaj-black) !important;
    box-shadow: 5px 5px 0px var(--toypaj-green) !important;
    transform: scale(1.02) !important;
  }
}
